require_once(__DIR__.'/../../init.php'); class map_common_logSetup { const TASK_NAME = 'mapCommonLogSetup'; private $db; private function log($message, $type = 0) { app_log($message, $type, self::TASK_NAME); } public function startLogArchive($params = null) { $date = new DateTime(); $strDate = $date->format('Ymd-His'); $rootPath = getServerRootPath(); $logPath = $rootPath . 'log\\'; $bakPath = $rootPath . 'bak\\'; $zipLogPath = $bakPath . 'MWSLOGS-' . $strDate . '.zip'; $filesToTruncate = []; $this->log('... Запущено архивирование лог-файлов.'); try { if (!file_exists($bakPath)) { mkdir($bakPath); } $zip = new ZipArchive(); $zip->open($zipLogPath, ZipArchive::CREATE | ZipArchive::OVERWRITE); $files = new RecursiveIteratorIterator( new RecursiveDirectoryIterator($logPath), RecursiveIteratorIterator::LEAVES_ONLY ); foreach ($files as $file) { if ($file->isFile()) { $filePath = $file->getRealPath(); $relativePath = substr($filePath, safe_strlen($logPath)); $zip->addFile($filePath, $relativePath); $filesToTruncate[] = $filePath; $this->log("        Добавлен в архив файл $file"); } } $zip->close(); foreach ($filesToTruncate as $file) { $fd = fopen($file, 'r+'); if ($fd !== false) { ftruncate($fd, 0); fclose($fd); } } } catch(Throwable $e) { $this->log("Ошибка $e"); throw $e; } return true; } } handleJsonRpc('map_common_logSetup');